-- Run only against an isolated test database. All fixtures roll back.
begin;
set local statement_timeout='30s';
create temporary table lodge_test_ids(key text primary key,id uuid);
grant select on lodge_test_ids to authenticated,anon;
insert into auth.users(id,email,raw_user_meta_data) values
 ('07110000-0000-0000-0000-000000000001','lodge-owner@example.invalid','{"full_name":"Lodge fixture owner"}'),
 ('07110000-0000-0000-0000-000000000002','lodge-other@example.invalid','{"full_name":"Other fixture owner"}'),
 ('07110000-0000-0000-0000-000000000003','housekeeper@example.invalid','{"full_name":"Housekeeping fixture"}'),
 ('07110000-0000-0000-0000-000000000004','lodge-admin@example.invalid','{"full_name":"Lodge oversight fixture"}'),
 ('07110000-0000-0000-0000-000000000005','reception@example.invalid','{"full_name":"Reception fixture"}');
insert into public.profiles(id,full_name) select id,raw_user_meta_data->>'full_name' from auth.users where id::text like '07110000-%' on conflict(id) do nothing;
insert into public.admin_role_assignments(user_id,role_id) values('07110000-0000-0000-0000-000000000004','super_admin');
create function pg_temp.assert_true(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',message;end if;end$$;

do $$declare l uuid;l2 uuid;other_l uuid;loc uuid;room uuid;room2 uuid;ty uuid;ty2 uuid;ty3 uuid;req uuid;v_reservation uuid;today date:=(now() at time zone 'Africa/Dar_es_Salaam')::date;result jsonb;pay uuid;inv uuid;failed boolean;before_payments bigint;begin
 select count(*) into before_payments from public.payment_intents;
 select id into loc from public.locations where is_active order by (location_type='ward') desc limit 1;
 perform set_config('request.jwt.claim.sub','07110000-0000-0000-0000-000000000001',true);
 l:=public.lodge_register(jsonb_build_object('name','Fixture lodge','location_id',loc,'location_label','Arusha fixture location','phone','255700000001','description','Independent rooms WiFi maegesho'));
 l2:=public.lodge_register(jsonb_build_object('name','Second lodge','location_id',loc,'location_label','Arusha fixture location','phone','255700000001'));
 insert into lodge_test_ids values('lodge',l),('second',l2);
 perform pg_temp.assert_true(jsonb_array_length(public.lodge_workspace()->'lodges')=2,'one owner can manage two lodges');
 begin perform public.lodge_command(l,'review','{"approved":true}');raise exception 'FAIL: owner self-verification';exception when insufficient_privilege then null;end;
 perform pg_temp.assert_true((public.public_lodges(p_id=>l)->>'total')::int=0,'pending lodge is private');
 ty:=(public.lodge_command(l,'save_room_type','{"name":"Deluxe","description":"Actual twin configuration","beds":"Twin beds","max_occupancy":2,"nightly_rate":10000,"currency":"TZS"}')->>'id')::uuid;
 ty2:=(public.lodge_command(l,'save_room_type','{"name":"Family","description":"Actual family configuration","beds":"Two beds","max_occupancy":4,"nightly_rate":20000,"currency":"TZS"}')->>'id')::uuid;
 ty3:=(public.lodge_command(l2,'save_room_type','{"name":"Standard","max_occupancy":2,"nightly_rate":10000}')->>'id')::uuid;
 result:=public.lodge_command(l,'save_room',('{"code":"100","room_type":"Deluxe","beds":"Twin beds","max_occupancy":2,"nightly_rate":10000,"currency":"TZS"}'::jsonb||jsonb_build_object('room_type_id',ty)));room:=(result->>'id')::uuid;
 result:=public.lodge_command(l,'save_room',('{"code":"101","room_type":"Family","beds":"Two beds","max_occupancy":4,"nightly_rate":20000,"currency":"TZS"}'::jsonb||jsonb_build_object('room_type_id',ty2)));room2:=(result->>'id')::uuid;
 insert into lodge_test_ids values('room',room),('room2',room2);
 begin perform public.lodge_command(l,'save_room',('{"code":" 100 ","room_type":"Standard","beds":"Bed","max_occupancy":2,"nightly_rate":10000}'::jsonb||jsonb_build_object('room_type_id',ty)));raise exception 'FAIL: duplicate code';exception when unique_violation then null;end;
 perform public.lodge_command(l2,'save_room',('{"code":"100","room_type":"Standard","beds":"Bed","max_occupancy":2,"nightly_rate":10000}'::jsonb||jsonb_build_object('room_type_id',ty3)));
 result:=public.lodge_command(l,'reserve',jsonb_build_object('room_ids',jsonb_build_array(room),'arrival',today+10,'departure',today+12,'guests',2,'guest_name','Private guest fixture','guest_phone','255799888777','channel','phone','status','confirmed'));
 v_reservation:=(result->'ids'->>0)::uuid;insert into lodge_test_ids values('v_reservation',v_reservation);
 begin perform public.lodge_command(l,'reserve',jsonb_build_object('room_ids',jsonb_build_array(room),'arrival',today+11,'departure',today+13,'guests',1,'guest_name','Overlap fixture','channel','walk_in','status','confirmed'));raise exception 'FAIL: overlap accepted';exception when exclusion_violation then null;end;
 perform public.lodge_command(l,'reserve',jsonb_build_object('room_ids',jsonb_build_array(room),'arrival',today+12,'departure',today+14,'guests',1,'guest_name','Turnover fixture','channel','whatsapp','status','confirmed'));
 perform public.lodge_command(l,'settings','{"allow_same_day_turnover":false,"publish_availability":true}');
 begin perform public.lodge_command(l,'reserve',jsonb_build_object('room_ids',jsonb_build_array(room),'arrival',today+14,'departure',today+15,'guests',1,'guest_name','Turnover disabled fixture','channel','direct','status','confirmed'));raise exception 'FAIL: disabled turnover allowed';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 perform public.lodge_command(l,'settings','{"allow_same_day_turnover":true}');
 begin perform public.lodge_command(l,'check_in',jsonb_build_object('id',v_reservation));raise exception 'FAIL: early check-in';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 result:=public.lodge_command(l,'reserve',jsonb_build_object('room_ids',jsonb_build_array(room2),'arrival',today,'departure',today+1,'guests',2,'guest_name','Walk-in fixture','channel','walk_in','status','confirmed'));
 perform public.lodge_command(l,'check_in',jsonb_build_object('id',result->'ids'->>0));
 perform pg_temp.assert_true((select condition='occupied' from public.lodge_rooms where id=room2),'check-in sets occupied');
 begin perform public.lodge_command(l,'room_condition',jsonb_build_object('id',room2,'condition','ready'));raise exception 'FAIL: occupied condition bypass';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 perform public.lodge_command(l,'check_out',jsonb_build_object('id',result->'ids'->>0));
 perform pg_temp.assert_true((select condition='cleaning' from public.lodge_rooms where id=room2),'check-out requires cleaning');
 perform public.lodge_command(l,'room_condition',jsonb_build_object('id',room2,'condition','maintenance'));
 perform public.lodge_command(l,'room_condition',jsonb_build_object('id',room2,'condition','ready'));
 result:=public.lodge_command(l,'record_payment',jsonb_build_object('reservation_id',v_reservation,'amount',5000,'method','Cash','reference','fixture-receipt'));
 pay:=(result->>'id')::uuid;
 perform pg_temp.assert_true((select sum(amount)=5000 from public.lodge_payments where reservation_id=v_reservation),'direct payment recorded');
 perform pg_temp.assert_true((select total_amount-(select sum(amount) from public.lodge_payments where reservation_id=v_reservation)=15000 from public.lodge_reservations where id=v_reservation),'outstanding balance');
 perform public.lodge_command(l,'reverse_payment',jsonb_build_object('id',pay,'reason','Incorrect receipt amount'));
 perform pg_temp.assert_true((select sum(amount)=0 from public.lodge_payments where reservation_id=v_reservation),'reversal preserves net balance');
 begin perform public.lodge_command(l,'reverse_payment',jsonb_build_object('id',pay,'reason','Repeated correction'));raise exception 'FAIL: double reversal';exception when unique_violation then null;end;
 begin update public.lodge_payments set amount=123 where id=pay;raise exception 'FAIL: payment edit';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 begin perform public.lodge_command(l,'reservation_update',jsonb_build_object('id',v_reservation,'arrival',today+9,'departure',today+12,'total_amount',30000));raise exception 'FAIL: accepted terms changed';exception when raise_exception then if SQLERRM not like 'Accepted reservation%' then raise;end if;end;
 perform public.lodge_command(l,'save_room_type',jsonb_build_object('id',ty,'name','Deluxe','max_occupancy',2,'nightly_rate',17000));
 perform pg_temp.assert_true((select total_amount=20000 and (accepted_terms->>'nightly_rate')::numeric=10000 from public.lodge_reservations where id=v_reservation),'type edit preserves accepted price');
 perform pg_temp.assert_true((select arrival=today+10 from public.lodge_reservations where id=v_reservation),'reservation modification');
 result:=public.lodge_command(l,'invite','{"email":"housekeeper@example.invalid","role":"housekeeping"}');
 insert into lodge_test_ids values('house-invite',(result->>'id')::uuid);
 result:=public.lodge_command(l,'invite','{"email":"reception@example.invalid","role":"receptionist"}');
 insert into lodge_test_ids values('reception-invite',(result->>'id')::uuid);
 perform set_config('request.jwt.claim.sub','07110000-0000-0000-0000-000000000003',true);
 perform public.lodge_command(l,'accept_invitation',jsonb_build_object('id',(select id from lodge_test_ids where key='house-invite')));
 perform public.lodge_command(l,'room_condition',jsonb_build_object('id',room2,'condition','cleaning'));
 perform pg_temp.assert_true((public.lodge_workspace(l,'calendar')->'rows') is not null,'housekeeping sees redacted calendar');
 begin perform public.lodge_workspace(l,'guests');raise exception 'FAIL: housekeeping guest access';exception when insufficient_privilege then null;end;
 begin perform public.lodge_command(l,'record_payment',jsonb_build_object('reservation_id',v_reservation,'amount',20,'method','Cash'));raise exception 'FAIL: housekeeping payment';exception when insufficient_privilege then null;end;
 begin perform public.lodge_workspace(l2,'calendar');raise exception 'FAIL: cross-lodge access';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','07110000-0000-0000-0000-000000000005',true);
 perform public.lodge_command(l,'accept_invitation',jsonb_build_object('id',(select id from lodge_test_ids where key='reception-invite')));
 begin perform public.lodge_command(l,'invite','{"email":"outsider@example.invalid","role":"manager"}');raise exception 'FAIL: receptionist elevation';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','07110000-0000-0000-0000-000000000002',true);
 other_l:=public.lodge_register(jsonb_build_object('name','Other owner lodge','location_id',loc,'location_label','Mwanza fixture location','phone','255700000002'));
 insert into lodge_test_ids values('other',other_l);
 begin perform public.lodge_command(l,'save_room',('{"code":"HACK","room_type":"Standard","beds":"Bed","max_occupancy":2,"nightly_rate":10000}'::jsonb||jsonb_build_object('room_type_id',ty)));raise exception 'FAIL: cross-tenant write';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','07110000-0000-0000-0000-000000000004',true);
 perform public.lodge_command(l,'review','{"approved":true,"notes":"Local fixture review"}');
 result:=public.public_lodges(p_id=>l,p_arrival=>today+10,p_departure=>today+11);
 perform pg_temp.assert_true((result->>'total')::int=1,'verified lodge appears publicly');
 perform pg_temp.assert_true(not(result::text like '%255799888777%') and not(result::text like '%Private guest%'),'public payload excludes guests');
 perform pg_temp.assert_true((select (x->>'available_rooms')::int=0 from jsonb_array_elements(result->'rows'->0->'room_types')x where x->>'room_type'='Deluxe'),'public availability respects confirmed v_reservation');
 result:=public.public_lodges(p_id=>l,p_arrival=>today+20,p_departure=>today+21);
 perform pg_temp.assert_true((select (x->>'available_rooms')::int=1 from jsonb_array_elements(result->'rows'->0->'room_types')x where x->>'room_type'='Deluxe'),'unreserved date is available');
 result:=public.lodge_command(l,'reserve',jsonb_build_object('room_ids',jsonb_build_array(room),'room_type_id',ty,'arrival',today+20,'departure',today+21,'guests',1,'channel','other','status','blocked'));
 perform public.lodge_command(l,'cancel',jsonb_build_object('id',result->'ids'->>0,'reason','Room block released'));
 perform set_config('request.jwt.claim.sub','07110000-0000-0000-0000-000000000001',true);
 req:=public.lodge_enquire(l,jsonb_build_object('room_type_id',ty,'arrival',today+20,'departure',today+21,'guests',1,'message','Request a room please','contact_phone','255700000001'));
 perform pg_temp.assert_true((select count(*)=0 from public.lodge_reservations where room_id=room and stay&&daterange(today+20,today+21,'[)') and status='confirmed'),'pending requests do not block inventory');
 perform public.lodge_command(l,'save_room_type',jsonb_build_object('id',ty,'name','Deluxe','max_occupancy',2,'nightly_rate',25000));
 result:=public.lodge_command(l,'confirm_enquiry',jsonb_build_object('id',req));
 perform pg_temp.assert_true((select room_id=room and total_amount=17000 and status='confirmed' and accepted_terms->>'room_type'='Deluxe' from public.lodge_reservations where id=(result->>'id')::uuid),'atomic allocation preserves requested quote after price edit');
 perform pg_temp.assert_true(public.lodge_command(l,'confirm_enquiry',jsonb_build_object('id',req))=result,'confirmation retry does not duplicate inventory');
 perform pg_temp.assert_true((public.lodge_my_requests(l)->0->>'confirmed')::boolean,'requesting account sees confirmation');
 perform pg_temp.assert_true(exists(select 1 from public.notifications where user_id=auth.uid() and payload->>'eventType'='lodge_confirmation'),'confirmation enters existing notification pipeline');
 begin perform public.lodge_enquire(l,jsonb_build_object('room_type_id',ty,'arrival',today+20,'departure',today+21,'guests',1,'message','Conflicting request','contact_phone','255700000001'));raise exception 'FAIL: request ignores existing confirmed allocation';exception when exclusion_violation then null;end;
 begin perform public.lodge_command(l,'save_room_type',jsonb_build_object('name','Invalid image','max_occupancy',2,'nightly_rate',1,'main_image',l2::text||'/photos/not-owned.jpg'));raise exception 'FAIL: unauthorized image';exception when raise_exception then if SQLERRM not like 'Choose an authorized%' then raise;end if;end;
 perform set_config('request.jwt.claim.sub','07110000-0000-0000-0000-000000000002',true);
 perform pg_temp.assert_true(jsonb_array_length(public.lodge_my_requests(l))=0,'request status is private to customer');
 perform set_config('request.jwt.claim.sub','07110000-0000-0000-0000-000000000001',true);

 perform public.lodge_command(l,'remove_staff','{"profile_id":"07110000-0000-0000-0000-000000000003"}');
 perform set_config('request.jwt.claim.sub','07110000-0000-0000-0000-000000000003',true);
 begin perform public.lodge_workspace(l,'calendar');raise exception 'FAIL: removed access retained';exception when insufficient_privilege then null;end;
 perform pg_temp.assert_true((select count(*) from public.payment_intents)=before_payments,'no marketplace payment intent created');
 raise notice 'PASS: lodge registration, multi-lodge scope, inventory, collisions, turnover, check-in/out, maintenance, payments, reversals, staff access, public availability, enquiry and isolation';
end $$;

set local role authenticated;
select set_config('request.jwt.claim.sub','07110000-0000-0000-0000-000000000002',true);
select pg_temp.assert_true((select count(*) from public.lodge_rooms where lodge_id=(select id from lodge_test_ids where key='lodge'))=0,'RLS hides another lodge rooms');
select pg_temp.assert_true((select count(*) from public.lodge_guests)=0,'RLS hides another lodge guests');
do $$begin begin insert into public.lodge_rooms(lodge_id,code,room_type,max_occupancy,nightly_rate) select id,'BYPASS','Standard',2,100 from lodge_test_ids where key='other';raise exception 'FAIL: direct room insert';exception when insufficient_privilege then null;end;end$$;
reset role;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select pg_temp.assert_true((public.public_lodges(p_id=>(select id from lodge_test_ids where key='lodge'))->>'total')::int=1,'anonymous public discovery');
do $$begin begin perform public.lodge_workspace();raise exception 'FAIL: anonymous workspace';exception when insufficient_privilege then null;end;end$$;
rollback;
